%[text] ## Datos de la simulación
clc; clear; close all;
warning('off','all') 
open_system('Sistema3') 
parameters.StopTime = '10';
parameters.Solver = 'ode15s';
parameters.MaxStep = '1e-2';

x = sim('Sistema3',parameters);
%[text] %[text:anchor:H_453F6DDC] ## Respuesta Control y Caso
plotsignals(x.t,x.F,x.Fsx,x.Fsy,x.PID,'Control y Caso') %[output:7e9c77e9]

%[text] ## Funcion: Respuesta de la simulación



function plotsignals(t,s,s1,s2,s3,signal)

set(figure(),'color','w')
set(gcf,'units','inches','position',[1,1,11,4.5])
set(gca,'fontname','times new roman','fontsize',11)

hold on;
grid off;
box on;

clr1 = [118, 196, 87]/225;
clr2 = [27, 44, 193]/225;
clr3 = [147, 112, 219]/225;
clr4 = [221, 113, 113]/225;

order = [clr1;clr2;clr3;clr4];
colororder(order)

if signal == "Control y Caso"

    plot(t,s,'-',t,s1,'-',t,s2,'--',t,s3,'--',...
        'LineWidth',1.5,'MarkerSize',5,...
        'MarkerIndices',1:1e3:length(t));

    L = legend('$F(t)$','$Fs(t): Control$',...
        '$Fs(t): Caso$','$PI(t): Tratamiento$');

end

set(L,'interpreter','latex',...
    'location','northoutside',...
    'orientation','horizontal')

title(L,[signal,' input'])

xlabel('$t$ [s]','interpreter','latex')
ylabel('$F(t)$ [V]','interpreter','latex')

xlim([0 10]);
xticks(0:1:10)

ylim([-0.1 1.1]);
yticks(-0.1:0.1:1.1)

exportgraphics(gcf,[signal,'_matlab3.pdf'],...
    'contenttype','vector')

end


